/* Source-grounded study support. Sidekick answers are generated locally from existing lesson materials. */
(async function(){
'use strict';
const KEY='holusStudyBuddyV1';
const app=document.getElementById('buddy-app');
const notice=document.getElementById('notice');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('en-CA');
const initial={course:'nutrition-counseling-education',lesson:'lesson-1',minutes:[0,6].includes(new Date().getDay())?120:60,remaining:58,deadline:'2026-12-24',reviews:{},positions:{},notes:{},sessions:[],timer:null};
let state={...initial},data,tab='guided',revealed=false,questionDraft='',sidekickResult=null,memoryOnly=false;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&typeof saved==='object'&&!Array.isArray(saved))state={...initial,...saved};}catch{memoryOnly=true;}
for(const k of ['reviews','positions','notes'])if(!state[k]||typeof state[k]!=='object'||Array.isArray(state[k]))state[k]={};
if(!Array.isArray(state.sessions))state.sessions=[];
for(const k of ['minutes','remaining'])if(typeof state[k]!=='number'&&typeof state[k]!=='string')state[k]=initial[k];
if(typeof state.deadline!=='string')state.deadline=initial.deadline;
state.positions=Object.fromEntries(Object.entries(state.positions).filter(([,v])=>Number.isInteger(v)&&v>=0));
state.notes=Object.fromEntries(Object.entries(state.notes).filter(([,v])=>typeof v==='string').map(([k,v])=>[k,v.slice(0,5000)]));
state.reviews=Object.fromEntries(Object.entries(state.reviews).filter(([,v])=>v&&typeof v==='object'&&['again','developing','secure'].includes(v.level)));

if(![15,30,60,120,180].includes(Number(state.minutes)))state.minutes=60;
if(!Number.isInteger(Number(state.remaining))||state.remaining<0||state.remaining>500)state.remaining=58;
if(!/^\d{4}-\d{2}-\d{2}$/.test(state.deadline)||!Number.isFinite(Date.parse(state.deadline)))state.deadline=initial.deadline;
if(state.timer&&(!Number.isFinite(state.timer.seconds)||state.timer.seconds<0||state.timer.seconds>10800||typeof state.timer.running!=='boolean'||!Number.isFinite(state.timer.started)))state.timer=null;
const message=t=>notice.textContent=t;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{memoryOnly=true;message('Browser storage is unavailable. You can study now, but these changes may disappear when you leave. Copy your handoff notes before closing.');}}
try{const res=await fetch('study-buddy-content.json?v=3');if(!res.ok)throw new Error('content');data=await res.json();if(!Array.isArray(data.courses)||!data.courses.length)throw new Error('content');}catch{app.innerHTML='<section class="card"><h2>Your lessons could not load.</h2><p>Please reload to retry, or <a href="/">open your course collection</a>. Your saved course progress has not been changed.</p></section>';return;}
const naturalHealth=globalThis.NHF_COURSE;
if(naturalHealth&&!data.courses.some(item=>item.id==='natural-health-fundamentals')){
 const sourceLabel=lesson=>`Supplied Natural Health Fundamentals PDFs · ${lesson.sources.filter(source=>source.role!=='test').map(source=>source.title).join(' · ')}`;
 data.courses.push({
  id:'natural-health-fundamentals',
  title:naturalHealth.title,
  path:'/courses/natural-health-fundamentals/',
  lessons:naturalHealth.lessons.map(lesson=>{
   const moments=lesson.modules.flatMap(module=>module.moments),source=sourceLabel(lesson);
   return {
    id:lesson.id,
    number:lesson.number,
    title:lesson.title,
    summary:lesson.lede,
    sourceLabel:source,
    guideUrl:`/courses/natural-health-fundamentals/#lesson-${lesson.number}`,
    recall:moments.map(moment=>({
     prompt:moment.check?.prompt||`Explain ${moment.title.toLowerCase()}.`,
     answer:[moment.highYield,...moment.keyPoints].join(' '),
     sourceLabel:source
    })),
    knowledge:moments.map(moment=>({
     title:moment.title,
     text:[moment.highYield,...moment.teaching,...moment.keyPoints,`Good to know: ${moment.goodToKnow}`,`In practice: ${moment.inPractice}`].join('\n\n'),
     sourceLabel:source
    }))
   };
  })
 });
}
const params=new URLSearchParams(location.search);
if(params.has('course'))state.course=params.get('course');
if(params.has('lesson'))state.lesson=params.get('lesson');
function course(){return data.courses.find(c=>c.id===state.course)||data.courses[0];}
function lesson(){return course().lessons.find(l=>l.id===state.lesson)||course().lessons[0];}
function sync(){state.course=course().id;state.lesson=lesson().id;}
sync();
const key=()=>`${state.course}/${state.lesson}`;
function cardIndex(){const p=Number(state.positions[key()]);return Number.isInteger(p)&&p>=0?p%lesson().recall.length:0;}
function card(){return lesson().recall[cardIndex()];}
function remainingSeconds(){if(!state.timer)return state.minutes*60;return Math.max(0,state.timer.seconds-(state.timer.running?Math.floor((Date.now()-state.timer.started)/1000):0));}
function clockText(){const s=remainingSeconds();return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function queue(){return Object.entries(state.reviews).filter(([,r])=>r&&r.level!=='secure').map(([k,r])=>{const [cid,lid]=k.split('/');const c=data.courses.find(x=>x.id===cid),l=c?.lessons.find(x=>x.id===lid);return c&&l?{key:k,r,c,l}:null;}).filter(Boolean).sort((a,b)=>(a.r.level==='again'?0:1)-(b.r.level==='again'?0:1));}
function plan(){const m=Number(state.minutes);if(m===15)return [[2,'Recall yesterday’s idea without notes'],[7,'Read one teaching section'],[4,'Try one recall card or source question'],[2,'Rate confidence and leave a next step']];if(m===30)return [[3,'Warm up with one recall card'],[15,'Work through one lesson section'],[8,'Practise without looking at the answer'],[4,'Check the guide, rate confidence, and recap']];if(m===60)return [[5,'Recall the last lesson'],[30,'Study the current lesson in depth'],[15,'Practise recall and use the lesson’s source quiz'],[10,'Check gaps, reflect, and choose your next step']];if(m===120)return [[10,'Retrieve key ideas from the last session'],[40,'Deep study: one focused lesson block'],[10,'Step away for a break'],[35,'Apply the lesson and practise source questions'],[15,'Review uncertain ideas'],[10,'Reflect and plan your next session']];return [[10,'Retrieve key ideas from the last session'],[45,'Deep study: first focused block'],[10,'Take a real break'],[45,'Deep study: second focused block'],[10,'Rest and reset'],[40,'Practise, check explanations, revisit gaps'],[20,'Connect the ideas and plan your next step']];}
function pace(){const end=new Date(state.deadline+'T23:59:59');const days=Math.max(0,Math.ceil((end-new Date())/86400000));return days?`${(Number(state.remaining)/(days/7)).toFixed(1)} units per week over about ${(days/7).toFixed(1)} weeks`:'Target date reached — update your plan';}
const STOP_WORDS=new Set('a an and are as at be because but by can could concept concepts describe did do does explain for from had has have help how i if in into is it its lesson me my of on or our please should so tell than that the their them then there these they this to topic topics understand was we were what when where which who why will with would you your'.split(' '));
function terms(text){return [...new Set((String(text??'').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').match(/[a-z0-9]+/g)||[]).filter(word=>word.length>2&&!STOP_WORDS.has(word)))];}
function sidekickSearch(question){
 const q=String(question??'').trim().slice(0,2000),l=lesson(),lower=q.toLowerCase();
 if(!q)return null;
 if(/^(quiz me|test me|question me|give me (a )?(quiz|practice|practise)( question)?|ask me (a )?(quiz|practice|practise)( question)?)(\b|$)/.test(lower)){const item=l.recall[cardIndex()];return {kind:'quiz',prompt:item.prompt,answer:item.answer,sourceLabel:item.sourceLabel||l.sourceLabel,revealed:false};}
 if(/^(summari[sz]e( this| the)? (lesson|key ideas?|main ideas?|key points?)|give me (a |the )?(summary|overview)|explain the key idea|what should i remember|key takeaways?|what are the (main ideas?|key ideas?|key points?|takeaways?)|show me the (main ideas?|key ideas?|key points?|takeaways?))(\b|$)/.test(lower)){return {kind:'summary',answer:l.summary,prompts:l.recall.slice(0,3).map(item=>item.prompt),sourceLabel:l.sourceLabel};}
 const query=terms(q),titleTerms=terms(l.title),summaryTerms=terms(l.summary);
 const candidates=[...l.recall.map(item=>({prompt:item.prompt,answer:item.answer,sourceLabel:item.sourceLabel||l.sourceLabel})),...(l.knowledge||[]).map(item=>({prompt:item.title,answer:item.text,sourceLabel:item.sourceLabel||l.sourceLabel}))];
 const ranked=candidates.map((item,index)=>{const promptTerms=terms(item.prompt),answerTerms=terms(item.answer);let score=0;for(const token of query){if(promptTerms.includes(token))score+=5;if(answerTerms.includes(token))score+=3;if(titleTerms.includes(token))score+=2;if(summaryTerms.includes(token))score+=1;}return {index,score,prompt:item.prompt,answer:item.answer,sourceLabel:item.sourceLabel};}).sort((a,b)=>b.score-a.score||a.index-b.index);
 const matches=ranked.filter(item=>item.score>0).slice(0,3);
 return matches.length?{kind:'match',matches}:{kind:'fallback',answer:l.summary,prompts:l.recall.slice(0,3).map(item=>item.prompt),sourceLabel:l.sourceLabel};
}
function sidekickResultHtml(){
 if(!sidekickResult)return '<div class="sidekick-empty"><p class="small">Ask in your own words, or choose a starter. The Sidekick searches this lesson’s existing explanations and recall cards.</p></div>';
 if(sidekickResult.kind==='quiz')return `<div class="sidekick-result" id="sidekick-response" tabindex="-1"><p class="eyebrow">RETRIEVAL CHECK</p><h3>${esc(sidekickResult.prompt)}</h3>${sidekickResult.revealed?`<div class="answer">${esc(sidekickResult.answer)}</div><p class="source">${esc(sidekickResult.sourceLabel)}</p>`:'<p class="muted">Answer aloud or on paper before revealing the guide answer.</p>'}<button id="sidekick-answer" class="secondary">${sidekickResult.revealed?'Hide guide answer':'Reveal guide answer'}</button></div>`;
 if(sidekickResult.kind==='match')return `<div class="sidekick-result" id="sidekick-response" tabindex="-1"><p class="eyebrow">CLOSEST LESSON MATCH</p><div class="sidekick-match"><h3>${esc(sidekickResult.matches[0].prompt)}</h3><div class="answer">${esc(sidekickResult.matches[0].answer)}</div></div>${sidekickResult.matches.length>1?`<details class="sidekick-related"><summary>Related ideas from this lesson</summary>${sidekickResult.matches.slice(1).map(item=>`<div><h3>${esc(item.prompt)}</h3><p>${esc(item.answer)}</p></div>`).join('')}</details>`:''}<p class="source">${esc(sidekickResult.matches[0].sourceLabel)}</p></div>`;
 const heading=sidekickResult.kind==='summary'?'Lesson in one clear idea':'I could not find a close phrase match';
 const intro=sidekickResult.kind==='summary'?'Start here, then use the questions below to check your understanding.':'Here is the lesson’s central idea. Try one of these lesson questions, or open the full lesson for more detail.';
 return `<div class="sidekick-result" id="sidekick-response" tabindex="-1"><p class="eyebrow">LESSON GUIDE</p><h3>${esc(heading)}</h3><p>${esc(intro)}</p><div class="answer">${esc(sidekickResult.answer)}</div><ul class="sidekick-prompts">${sidekickResult.prompts.map(prompt=>`<li>${esc(prompt)}</li>`).join('')}</ul><p class="source">${esc(sidekickResult.sourceLabel)}</p></div>`;
}
function render(){sync();const c=course(),l=lesson(),q=queue(),r=state.reviews[key()];
app.innerHTML=`<div class="layout"><aside class="sidebar stack"><section class="card"><p class="eyebrow">TODAY’S FOCUS</p><h2>Where shall we begin?</h2><label for="course">Course</label><select id="course">${data.courses.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select><label for="lesson">Lesson</label><select id="lesson">${c.lessons.map(x=>`<option value="${x.id}" ${x.id===l.id?'selected':''}>${x.number}. ${esc(x.title)}</option>`).join('')}</select><p class="small">This is your buddy’s focus. Your course completion and quiz answers are left untouched.</p><a class="button secondary full" href="${esc(l.guideUrl)}">Open full lesson ↗</a><p class="small">Use the source quiz inside your lesson. The cards here are supplementary recall, not an official test.</p></section><section class="card"><p class="eyebrow">MAKE ROOM FOR REVIEW</p><h2>Your revisit list <span class="count">(${q.length})</span></h2>${q.length?`<ul class="queue">${q.map(x=>`<li><button data-review="${esc(x.key)}">${esc(x.l.title)}</button><small>${esc(x.c.title)} · ${x.r.level==='again'?'Revisit soon':'Developing confidence'}</small></li>`).join('')}</ul>`:'<p class="empty">Nothing queued yet. Rate a lesson “Revisit” or “Getting there” to keep it close.</p>'}<p class="small">Your self-ratings, not a mastery score. “Confident” removes a lesson from this list.</p></section></aside><div class="stack"><div class="tabbar" aria-label="Buddy modes"><button data-tab="guided" aria-pressed="${tab==='guided'}">Guided buddy</button><button data-tab="live" aria-pressed="${tab==='live'}">Ask sidekick</button></div>${tab==='guided'?`<section class="card dark"><div class="row between"><span class="tag">${esc(c.title)}</span><span class="small" style="color:#d6e0db">Lesson ${l.number}</span></div><h2 style="font-size:30px;margin-top:20px">${esc(l.title)}</h2><p>${esc(l.summary)}</p><p class="source" style="color:#d6e0db">${esc(l.sourceLabel)}</p></section><section class="card"><div class="row between"><div><p class="eyebrow">A SESSION THAT FITS YOUR DAY</p><h2>Make a little progress.</h2></div><span class="tag">No completion pressure</span></div><label for="minutes">Time available</label><select id="minutes">${[[15,'15 minutes · quick revisit'],[30,'30 minutes · focused block'],[60,'60 minutes · weekday'],[120,'2 hours · weekend'],[180,'3 hours · weekend']].map(([n,t])=>`<option value="${n}" ${Number(state.minutes)===n?'selected':''}>${t}</option>`).join('')}</select><ol class="plan">${plan().map(([n,t])=>`<li><b>${n} min</b><span>${t}</span></li>`).join('')}</ol><div class="row between"><div><div class="metric" id="timer" role="timer" aria-label="Session time remaining">${clockText()}</div><p class="small" id="timer-label">${state.timer?.running?'Session running':state.timer?'Session paused':'Ready when you are'}</p></div><div class="row"><button id="timer-toggle">${state.timer?.running?'Pause':state.timer?'Resume':'Start session'}</button><button id="timer-reset" class="secondary">Reset timer</button></div></div><p class="small">A running timer keeps wall-clock time if you leave this page. Pause before a longer interruption. Changing duration resets it.</p></section><section class="card" id="recall"><div class="row between"><p class="eyebrow">RETRIEVE BEFORE YOU RE-READ</p><span class="count">Card ${cardIndex()+1} of ${l.recall.length}</span></div><h2>Say it in your own words.</h2><p class="recall-prompt">${esc(card().prompt)}</p>${revealed?`<div class="answer">${esc(card().answer)}</div><p class="source">${esc(card().sourceLabel||l.sourceLabel)}</p>`:'<p class="muted">Try answering aloud or on paper first. Then compare with your existing guide.</p>'}<div class="row"><button id="reveal">${revealed?'Hide guide answer':'Reveal guide answer'}</button><button id="next" class="secondary">Next card →</button></div><hr class="divider"><h3>How does this lesson feel?</h3><p class="small">Rate the lesson after a few cards. This never marks a course or exam complete.${r?` Current rating: ${esc(r.level==='again'?'Revisit':r.level==='developing'?'Getting there':'Confident')}.`:''}</p><div class="row rating"><button data-rate="again" class="secondary">Revisit</button><button data-rate="developing" class="secondary">Getting there</button><button data-rate="secure" class="secondary">Confident</button></div></section><section class="card"><p class="eyebrow">LEAVE A THREAD FOR NEXT TIME</p><h2>What clicked? What’s still fuzzy?</h2><label for="note">Your lesson note</label><textarea id="note" maxlength="5000" placeholder="I can explain… / I want to revisit…">${esc(state.notes[key()]||'')}</textarea><p class="small" id="note-state">Notes save as you type, in this browser only.</p><button id="log" class="secondary">Save session reflection</button><p class="small">${state.sessions.length} reflection${state.sessions.length===1?'':'s'} saved. A reflection is not a completed lesson.</p></section>`:livePanel(c,l)}<section class="card"><p class="eyebrow">YOUR CHRISTMAS DIRECTION</p><h2>A plan, not a promise.</h2><div class="inline-controls"><div><label for="remaining">Your remaining units estimate</label><input id="remaining" type="number" min="0" max="500" step="1" value="${esc(state.remaining)}"></div><div><label for="deadline">Target date</label><input id="deadline" type="date" value="${esc(state.deadline)}"></div></div><p><strong>${esc(pace())}</strong></p><p class="small">Your estimate starts at 58. This hub currently lists 50 lessons + 3 final-exam slots = 53 catalog units; this is not a verified count of what you personally have left. Finals are not supplied here. Adjust your estimate to include outstanding assignments or external work.</p><p class="small">With 1 hour each weekday and 2–3 hours each weekend day, that is 9–11 study hours per week. Units vary in length; this pace is a planning guide, not a finish-date guarantee. Remaining units only change when you edit them.</p><details><summary>Take your study context with you</summary><p class="small">Create a lesson handoff if you want to continue in your existing ChatGPT conversation. Nothing is sent automatically.</p><button id="handoff" class="secondary">Prepare lesson handoff</button><div id="handoff-output"></div></details></section></div></div>`;
bind();updateTimer();if(memoryOnly)message('Browser storage is unavailable. Your changes are only kept for this visit.');}
function livePanel(c,l){return `<section class="card live sidekick-panel"><div class="row between"><span class="tag">Ready · private and lesson-grounded</span><span class="small">${esc(c.title)} · Lesson ${l.number}</span></div><h2>Ask your lesson Sidekick.</h2><p>Type what is confusing. The Sidekick searches the explanations and recall cards already built for <strong>${esc(l.title)}</strong>, then shows the closest grounded answer. It does not guess beyond this lesson or send your question anywhere.</p><div class="starter-row" aria-label="Sidekick question starters"><button class="secondary" data-sidekick-prompt="Explain the key idea">Explain the key idea</button><button class="secondary" data-sidekick-prompt="Quiz me on this lesson">Quiz me</button><button class="secondary" data-sidekick-prompt="What should I remember?">Key takeaways</button></div><label for="sidekick-question">What are you trying to understand?</label><textarea id="sidekick-question" maxlength="2000" placeholder="For example: What is osmosis, and why does it matter?">${esc(questionDraft)}</textarea><div class="row" style="margin-top:15px"><button id="sidekick-ask">Ask Sidekick</button><button id="sidekick-clear" class="secondary">Clear</button><a class="button secondary" href="${esc(l.guideUrl)}">Open full lesson ↗</a></div>${sidekickResultHtml()}<details class="chatgpt-handoff"><summary>Continue this question in ChatGPT</summary><p class="small">Prepare the lesson context and your question for copying. Nothing is sent automatically.</p><button id="live-handoff" class="secondary">Prepare ChatGPT handoff</button><div id="live-output"></div></details></section>`;}
function switchFocus(cid,lid){state.course=cid;state.lesson=lid;sync();revealed=false;questionDraft='';sidekickResult=null;save();render();history.replaceState(null,'',`?course=${encodeURIComponent(state.course)}&lesson=${encodeURIComponent(state.lesson)}`);}
function prepare(question=''){return `Please be my study buddy for ${course().title}, lesson ${lesson().number}: ${lesson().title}.\n\nAsk me one question at a time and help me reason rather than simply giving the answer. Ground discussion in the following supplied excerpt; distinguish it from outside knowledge and flag uncertainty. Do not claim this is an official answer key or complete textbook chapter. Do not claim to access my private Site.\n\nExisting guide excerpt:\n${lesson().summary}\n\nRecall question: ${card().prompt}\nGuide explanation: ${card().answer}\n\nMy note: ${state.notes[key()]||'(none)'}\nMy question: ${question||'Help me practise and check my understanding.'}\n\nSource: ${lesson().sourceLabel}`;}
function handoff(container,question){const copyText=prepare(question);const uid=container.id+'-text';container.innerHTML=`<div class="export-area"><label for="${uid}">Ready to copy — paste into your existing ChatGPT chat</label><textarea id="${uid}" readonly>${esc(copyText)}</textarea><button class="secondary" data-copy-handoff>Copy handoff</button><p class="small" data-copy-status></p></div>`;container.querySelector('[data-copy-handoff]').onclick=async()=>{try{await navigator.clipboard.writeText(copyText);container.querySelector('[data-copy-status]').textContent='Copied. Paste it into your existing ChatGPT conversation.';}catch{document.getElementById(uid).select();container.querySelector('[data-copy-status]').textContent='Automatic copying is unavailable. The text is selected; use your device’s Copy command.';}};}
function bind(){document.getElementById('course').onchange=e=>{switchFocus(e.target.value,'lesson-1');document.getElementById('course').focus({preventScroll:true});};document.getElementById('lesson').onchange=e=>{switchFocus(state.course,e.target.value);document.getElementById('lesson').focus({preventScroll:true});};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();document.querySelector('[data-tab="'+tab+'"]').focus({preventScroll:true});});document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const [c,l]=b.dataset.review.split('/');tab='guided';switchFocus(c,l);});document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{const level=b.dataset.rate;state.reviews[key()]={level,date:today()};save();render();document.querySelector('[data-rate="'+level+'"]').focus({preventScroll:true});message('Lesson confidence saved. Your course and exam progress have not changed.');});
const on=(id,fn)=>{const el=document.getElementById(id);if(el)el.onclick=fn;};
on('reveal',()=>{revealed=!revealed;render();document.getElementById('reveal').focus({preventScroll:true});});on('next',()=>{state.positions[key()]=(cardIndex()+1)%lesson().recall.length;revealed=false;save();render();document.getElementById('next').focus({preventScroll:true});});
const minutes=document.getElementById('minutes');if(minutes)minutes.onchange=e=>{state.minutes=Number(e.target.value);state.timer=null;save();render();};
on('timer-toggle',()=>{const seconds=remainingSeconds();state.timer=state.timer?.running?{seconds,started:Date.now(),running:false}:{seconds:seconds||state.minutes*60,started:Date.now(),running:true};save();render();});on('timer-reset',()=>{state.timer=null;save();render();});
const note=document.getElementById('note');if(note)note.oninput=e=>{state.notes[key()]=e.target.value;save();document.getElementById('note-state').textContent=memoryOnly?'Kept for this visit only; storage is unavailable.':'Saved on this browser.';};
on('log',()=>{state.sessions.push({date:today(),lesson:key(),note:state.notes[key()]||''});state.sessions=state.sessions.slice(-100);save();render();message('Reflection saved. No lesson or exam has been marked complete.');});
document.getElementById('remaining').onchange=e=>{const n=Number(e.target.value);if(!e.target.value||!Number.isInteger(n)||n<0||n>500){message('Enter a whole number from 0 to 500.');e.target.value=state.remaining;return;}state.remaining=n;save();render();};document.getElementById('deadline').onchange=e=>{if(!e.target.value)return;state.deadline=e.target.value;save();render();};on('handoff',()=>handoff(document.getElementById('handoff-output')));
const askSidekick=question=>{questionDraft=String(question??'').trim().slice(0,2000);if(!questionDraft){message('Type a question or choose a starter so the Sidekick knows what to retrieve.');document.getElementById('sidekick-question')?.focus();return;}sidekickResult=sidekickSearch(questionDraft);render();document.getElementById('sidekick-response')?.focus({preventScroll:true});};
const sidekickQuestion=document.getElementById('sidekick-question');if(sidekickQuestion)sidekickQuestion.oninput=e=>questionDraft=e.target.value;
on('sidekick-ask',()=>askSidekick(sidekickQuestion?.value));document.querySelectorAll('[data-sidekick-prompt]').forEach(button=>button.onclick=()=>askSidekick(button.dataset.sidekickPrompt));
on('sidekick-clear',()=>{questionDraft='';sidekickResult=null;render();document.getElementById('sidekick-question')?.focus({preventScroll:true});});
on('sidekick-answer',()=>{if(sidekickResult?.kind==='quiz'){sidekickResult.revealed=!sidekickResult.revealed;render();document.getElementById('sidekick-answer')?.focus({preventScroll:true});}});
on('live-handoff',()=>handoff(document.getElementById('live-output'),questionDraft));}
function updateTimer(){const el=document.getElementById('timer');if(el)el.textContent=clockText();if(state.timer?.running&&remainingSeconds()===0){state.timer={seconds:0,started:Date.now(),running:false};save();message('Your session time is up. Take a breath, note what clicked, and choose whether to continue. Nothing is marked complete automatically.');const b=document.getElementById('timer-toggle');if(b)b.textContent='Start again';const label=document.getElementById('timer-label');if(label)label.textContent='Session time finished';}}
render();setInterval(updateTimer,1000);
})();
